import React, { useState, useEffect, useRef } from "react";
import { Menubar } from "primereact/menubar";
import { Button } from "primereact/button";
import { Avatar } from "primereact/avatar";
import { Menu } from "primereact/menu";
import { useNavigate } from "react-router-dom";
import "primereact/resources/themes/lara-light-indigo/theme.css";
import "primereact/resources/primereact.min.css";
import "primeicons/primeicons.css";
import '../styles/navBar.css'

export const Navigation = () => {
    const [isLoggedIn, setIsLoggedIn] = useState(!!localStorage.getItem("token"));
    const [avatar, setAvatar] = useState("");
    const menu = useRef(null);
    const navigate = useNavigate();

    useEffect(() => {
        const token = localStorage.getItem("token");
        setIsLoggedIn(!!token);
        const ownerData = localStorage.getItem("owner");
        if (ownerData) {
            const owner = JSON.parse(ownerData);
            setAvatar(owner.avatar || "default-avatar.png");
        }
    }, []);

    const handleLogout = () => {
        localStorage.removeItem("token");
        localStorage.removeItem("ownerId");
        setIsLoggedIn(false);
        navigate("/login");
    };

    const handleProfileClick = () => {
        const ownerId = localStorage.getItem("ownerId");
        if (ownerId) {
            navigate(`/profile/${ownerId}`);
        }
    };

    const menuItems = [
        { label: "Home", icon: "pi pi-home", command: () => navigate("/") },
        { label: "Services", icon: "pi pi-cog", command: () => navigate("/services") },
        { label: "Contact", icon: "pi pi-envelope", command: () => navigate("/contact") },
    ];

    const profileMenuItems = [
        { label: "Profile", icon: "pi pi-user", command: handleProfileClick },
        { label: "Logout", icon: "pi pi-sign-out", command: handleLogout },
    ];

    return (
        <Menubar
            model={menuItems}
            start={<img src={require("../assets/Logo.png")} alt="Petopia Logo" className="logo" />}
            end={
                isLoggedIn ? (
                    <>
                        <Avatar
                            image={avatar}
                            className="p-mr-2 avatar"
                            shape="circle"
                            onClick={(e) => menu.current.toggle(e)}
                        />
                        <Menu model={profileMenuItems} popup ref={menu} />
                    </>
                ) : (
                    <Button label="Log In" icon="pi pi-sign-in" className="p-button-rounded p-button-outlined" onClick={() => navigate("/login")} />
                )
            }
        />
    );
};
